function showSubmenu(e){document.getElementById(e).classList.toggle("show")}window.onclick=function(e){if(!e.target.matches(".dropdown-parent")){var t,n=document.getElementsByClassName("dropdown-content");for(t=0;t<n.length;t++){var s=n[t];s.classList.contains("show")&&s.classList.remove("show")}}};const mobileToggleButton=document.getElementsByClassName("mobile-nav-toggle")[0],navbarLinks=document.getElementsByClassName("navbar-links")[0];mobileToggleButton.addEventListener("click",()=>{navbarLinks.classList.toggle("show")});